import z3
import itertools

n = 22
edges = []
edge_index = {}
idx = 0
for i in range(n):
    for j in range(i+1, n):
        edges.append((i, j))
        edge_index[(i, j)] = idx
        idx += 1

print(f"Number of edges: {len(edges)}")

# Create Z3 variables
edge_vars = [z3.Bool(f"e_{i}_{j}") for (i, j) in edges]

solver = z3.Solver()

# For each 4-clique, not all edges are red (0)
# For each 5-clique, not all edges are blue (1)

# Red = False (0), Blue = True (1)

# No red K4: for each set of 4 vertices, at least one edge is blue (True)
for clique in itertools.combinations(range(n), 4):
    # At least one edge in this 4-set is blue
    clause = []
    for i in range(4):
        for j in range(i+1, 4):
            a, b = clique[i], clique[j]
            if a < b:
                idx = edge_index[(a, b)]
            else:
                idx = edge_index[(b, a)]
            clause.append(edge_vars[idx])
    solver.add(z3.Or(clause))

print("Added 4-clique constraints")

# No blue K5: for each set of 5 vertices, at least one edge is red (False)
for clique in itertools.combinations(range(n), 5):
    clause = []
    for i in range(5):
        for j in range(i+1, 5):
            a, b = clique[i], clique[j]
            if a < b:
                idx = edge_index[(a, b)]
            else:
                idx = edge_index[(b, a)]
            clause.append(z3.Not(edge_vars[idx]))
    solver.add(z3.Or(clause))

print("Added 5-clique constraints")
print("Solving...")

result = solver.check()
print(f"Result: {result}")

if result == z3.sat:
    model = solver.model()
    solution = []
    for (i, j) in edges:
        val = model.evaluate(edge_vars[edge_index[(i, j)]])
        if val:
            solution.append(1)
        else:
            solution.append(0)
    print(f"Solution length: {len(solution)}")
    print(f"First 20: {solution[:20]}")

    # Verify
    # Check no red K4
    for clique in itertools.combinations(range(n), 4):
        all_red = True
        for i in range(4):
            for j in range(i+1, 4):
                a, b = clique[i], clique[j]
                if a < b:
                    idx = edge_index[(a, b)]
                else:
                    idx = edge_index[(b, a)]
                if solution[idx] == 1:  # blue
                    all_red = False
                    break
            if not all_red:
                break
        if all_red:
            print(f"ERROR: Red K4 found: {clique}")
            break
    else:
        print("No red K4 found - OK")

    # Check no blue K5
    for clique in itertools.combinations(range(n), 5):
        all_blue = True
        for i in range(5):
            for j in range(i+1, 5):
                a, b = clique[i], clique[j]
                if a < b:
                    idx = edge_index[(a, b)]
                else:
                    idx = edge_index[(b, a)]
                if solution[idx] == 0:  # red
                    all_blue = False
                    break
            if not all_blue:
                break
        if all_blue:
            print(f"ERROR: Blue K5 found: {clique}")
            break
    else:
        print("No blue K5 found - OK")

